import type { A1ListeningEpisode, A1ListeningSeries, EpisodeAudit, Question } from './schema'

/**
 * Temporada 2 de «노란 우산의 주인» (coreano-a1-series.ts): mismo reparto, dos meses después.
 *
 * Notas de esquema, para que no se lean como descuidos:
 * - `EpisodeAudit.level` sigue siendo `'A1'` porque el tipo de schema.ts lo fija como literal
 *   y `scripts/validate-listening-series.mjs` comprueba `audit.level !== 'A1'` para toda serie.
 *   El nivel real de la serie se declara una sola vez, en `level: 'A2'`.
 * - La romanización es Romanización Revisada y transcribe la PRONUNCIACIÓN, no la ortografía.
 *   Criterio único ante ㅎ en toda la serie: la aspiración se funde (비슷해요 → biseutaeyo,
 *   연습하고 → yeonseupago, 급해서 → geupaeseo). El guion solo aparece cuando desambigua sílaba.
 * - Registro: 해요체 general. 지호 y 별 acuerdan 반말 en el episodio 13 y desde ahí lo usan
 *   entre ellos —y solo entre ellos—; con 소피아, 미나, 유나, 김 선생님 y la señora de la
 *   papelería vuelven al 해요체 en la misma escena.
 */

type Spec = [string, string, string, string, string]
const question = ([prompt, correct, wrong1, wrong2, feedback]: Spec): Question => {
  const answer = [...prompt].reduce((sum, char) => sum + char.codePointAt(0)!, 0) % 3
  const options = [wrong1, wrong2]
  options.splice(answer, 0, correct)
  return { prompt, options, answer, feedback }
}

type Draft = Omit<A1ListeningEpisode, 'ttsScript' | 'gist' | 'details' | 'consolidation' | 'audit'> & {
  gist: Spec
  details: [Spec, Spec, Spec]
  consolidation: Spec
  audit: Omit<EpisodeAudit, 'level' | 'estimatedDuration' | 'grammarUsed' | 'newVocabulary'>
}

const ep = (draft: Draft): A1ListeningEpisode => ({
  ...draft,
  ttsScript: draft.turns.map((turn) => turn.target).join(' '),
  gist: question(draft.gist),
  details: draft.details.map(question) as [Question, Question, Question],
  consolidation: question(draft.consolidation),
  audit: {
    level: 'A2',
    grammarUsed: draft.grammar,
    newVocabulary: draft.keywords.map((word) => word.target),
    estimatedDuration: draft.duration,
    ...draft.audit,
  },
})


